      jj_la1_2 = new int[] {0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x800000,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x0,0x7,0x38,0x2000,0x1f00,0x0,0x0,0x85a000,0x0,0x0,0x0,0x0,0x0,0x800000,0x800000,0x380000,0x0,0x800000,0x800000,0x400000,0x0,0x0,0x0,0x800000,0x800000,0xf8,0x3000000,0xff7fff37,};
